    }
  ],
  "additional_findings": [
    {
      "finding_id": "AD-1",
      "drift_kind": "other",
      "explanation": "The documented custom SchemaOpts subclass passes **kwargs to SchemaOpts.__init__, but the actual SchemaOpts.__init__ accepts only meta and will reject those keyword arguments.",
      "doc_citation": {
        "path": "docs/extending/custom_options.rst",
        "start_line": 39,
        "end_line": 42,
        "quote": "        \"\"\"Same as the default class Meta options, but adds \"name\" and\n        \"plural_name\" options for enveloping.\n        \"\"\"\n\n        def __init__(self, meta, **kwargs):\n            SchemaOpts.__init__(self, meta, **kwargs)"
      },
      "code_citation": {
        "path": "src/marshmallow/schema.py",
        "start_line": 205,
        "end_line": 205,
        "quote": "    def __init__(self, meta: type):"
      },
      "proposed_fix": "Change the example to call `SchemaOpts.__init__(self, meta)` and remove the unsupported `**kwargs` forwarding."
    },
    {
      "finding_id": "AD-2",
      "drift_kind": "config_key",
      "explanation": "The Meta documentation advertises an additional option, but SchemaOpts never reads or implements it.",
      "doc_citation": {
        "path": "src/marshmallow/schema.py",
        "start_line": 362,
        "end_line": 365,
        "quote": "        additional: typing.ClassVar[tuple[str, ...] | list[str]]\n        \"\"\"Fields to include in addition to the explicitly declared fields.\n        `additional <marshmallow.Schema.Meta.additional>` and `fields <marshmallow.Schema.Meta.fields>`\n        are mutually-exclusive options.\n        \"\"\""
      },
      "code_citation": {
        "path": "src/marshmallow/schema.py",
        "start_line": 205,
        "end_line": 223,
        "quote": "    def __init__(self, meta: type):\n        self.fields = getattr(meta, \"fields\", ())\n        if not isinstance(self.fields, (list, tuple)):\n            raise ValueError(\"`fields` option must be a list or tuple.\")\n        self.exclude = getattr(meta, \"exclude\", ())\n        if not isinstance(self.exclude, (list, tuple)):\n            raise ValueError(\"`exclude` must be a list or tuple.\")\n        self.dateformat = getattr(meta, \"dateformat\", None)\n        self.datetimeformat = getattr(meta, \"datetimeformat\", None)\n        self.timeformat = getattr(meta, \"timeformat\", None)\n        self.render_module = getattr(meta, \"render_module\", json)\n        self.index_errors = getattr(meta, \"index_errors\", True)\n        self.include = getattr(meta, \"include\", {})\n        self.load_only = getattr(meta, \"load_only\", ())\n        self.dump_only = getattr(meta, \"dump_only\", ())\n        self.unknown = getattr(meta, \"unknown\", RAISE)\n        self.register = getattr(meta, \"register\", True)\n        self.many = getattr(meta, \"many\", False)"
      },
      "proposed_fix": "Either remove the documented `additional` option or implement support for it in SchemaOpts and field initialization."
    }
  ]
}
